const input = $input.first().json;
const body = input.body || input;
const ticketId = String(body.ticket_id || '').trim();
const bodyText = String(body.body_text || '').trim();
const idempotencyKey = String(body.idempotency_key || '').trim();
const clerkUserId = String(body.clerk_user_id || '').trim();

if (!ticketId || !bodyText || !idempotencyKey || !clerkUserId) {
  throw new Error('ticket_id, body_text, idempotency_key, and clerk_user_id are required');
}

return [{
  json: {
    ticket_id: ticketId,
    body_text: bodyText,
    idempotency_key: idempotencyKey,
    clerk_user_id: clerkUserId,
    payload_json: JSON.stringify({
      source: 'operator-console',
      clerk_user_id: clerkUserId,
      idempotency_key: idempotencyKey,
      demo_delivery: 'db_only_no_twilio'
    })
  }
}];
